+static void join_argv_tokens(int argc, char **argv, int from, int to,
+                             char *out, unsigned out_sz)
+{
+  int i;
+  unsigned n = 0;
+
+  if (out_sz == 0) {
+    return;
+  }
+  out[0] = '\0';
+  if (from > to || from >= argc) {
+    return;
+  }
+  if (to >= argc) {
+    to = argc - 1;
+  }
+  for (i = from; i <= to; i++) {
+    const char *s = argv[i];
+    size_t len;
+
+    if (s == NULL) {
+      continue;
+    }
+    len = strlen(s);
+    if (i > from && n + 1 < out_sz) {
+      out[n++] = ' ';
+    }
+    if (n + len + 1 > out_sz) {
+      len = out_sz - n - 1;
+    }
+    memcpy(out + n, s, len);
+    n += len;
+    out[n] = '\0';
+  }
+}
