  memset(&t, 0, sizeof(t));
  t.valid = true;
  t.range_m = range_m;
  t.speed_kmh = speed;
  t.snr = 30.0f;
  t.approaching = (speed > 0.0f);
  t.ttc_s = t.approaching ? (t.range_m / (t.speed_kmh / 3.6f)) : -1.0f;
