int ew_wifi_scan(ew_wifi_ap_t *aps, int max)
{
  char resp[160];
  int count = 0;
  int fd;

  if (aps == NULL || max <= 0) {
    return -1;
  }

  fd = at_begin();
  if (fd < 0) {
    return -1;
  }
  if (at_wake_light(fd) != 0) {
    /* 轻量握手失败再试完整 wake（含 RST） */
    if (at_wake(fd) != 0) {
      at_end(fd);
      return -1;
    }
  }

  /* Scan independently of the current connection, across CN channels 1-13. */
  (void)at_tx(fd, "AT+CWQAP", resp, sizeof(resp), 1500, 4000, 0);
  (void)at_tx(fd, "AT+SLEEP=0", resp, sizeof(resp), 800, 1500, 0);
  (void)at_tx(fd, "AT+CWCOUNTRY=1,\"CN\",1,13", resp, sizeof(resp),
              800, 1500, 0);
  if (!resp_ok(resp)) {
    printf("[ew-at] country setup failed; scan channel coverage unconfirmed\n");
    print_rx(resp);
  }
  usleep(500000);

  (void)scan_run_once(fd, aps, max, &count, 0);

  /* Merge retries when the first scan returns few distinct SSIDs. */
  if (count <= 3) {
    usleep(1000000);
    (void)scan_run_once(fd, aps, max, &count, 0);
  }
  if (count <= 3) {
    usleep(1500000);
    (void)scan_run_once(fd, aps, max, &count, 1);
  }

  /* Supplement the scan with saved and manually entered SSIDs. */
  scan_directed_all(fd, aps, max, &count);

  scan_sort_rssi(aps, count);
  at_drain_rx(fd, 400);
  at_end(fd);

  printf("[ew-at] scan found %d ap\n", count);
  fflush(stdout);
  return count;
}

