static void *ctl_reader(void *arg)
{
  int fd = (intptr_t)arg;
  char line[EW_CTL_LINE_MAX];
  int pos = 0;

  (void)arg;
  for (;;) {
    struct pollfd pfd;
    char c;
    ssize_t n;

    pfd.fd = fd;
    pfd.events = POLLIN;
    if (poll(&pfd, 1, 120) <= 0) {
      continue;
    }
    n = read(fd, &c, 1);
    if (n != 1) {
      usleep(50000);
      continue;
    }
    if (c == '\r' || c == '\n') {
      if (pos > 0) {
        line[pos] = '\0';
        if (line[0] == '@') {
          q_push(line + 1);
        }
        pos = 0;
      }
      continue;
    }
    if (pos + 1 < (int)sizeof(line)) {
      line[pos++] = c;
    }
  }
  return NULL;
}

void ew_serial_ctl_start(void)
{
  pthread_t tid;
  int fd;

  if (g_reader_started) {
    return;
  }
  g_reader_started = 1;
  pthread_mutex_init(&g_q.mu, NULL);

  fd = open("/dev/console", O_RDONLY);
  if (fd < 0) {
    fd = STDIN_FILENO;
  }
  if (pthread_create(&tid, NULL, ctl_reader, (void *)(intptr_t)fd) != 0) {
    printf("[ew-ctl] reader thread failed\n");
    return;
  }
  pthread_detach(tid);
  printf("[ew-ctl] remote @ commands on console (PC panel)\n");
}

void ew_serial_ctl_poll(void)
{
  char line[EW_CTL_LINE_MAX];

  while (q_pop(line, sizeof(line))) {
    ctl_dispatch(line);
  }
}

