    sp.dtr = sp.rts = False
    sp.port = args.port
    with sp, log.open("w", encoding="utf-8") as fp, log.with_suffix(".bin").open("wb") as raw:
        if args.reset:
            sp.dtr = True
            time.sleep(0.15)
            sp.dtr = False
            deadline = time.monotonic() + 20
