  }
  p += 7;
  while (*p == ' ' || *p == '\t') {
    p++;
  }
  if (*p++ != '(' || *p < '0' || *p > '9') {
    return -1;
  }
  ecn = strtol(p, &end, 10);
  if (ecn < 0 || ecn > 14 || *end != ',' || end[1] != '"') {
    return -1;
  }
