    if (*q == '\\') {
      q++;
      if (*q == '\0') {
        return -1;
      }
    }
    if (len + 1 >= sizeof(ap->ssid)) {
      return -1;
    }
    ap->ssid[len++] = *q++;
  }
  /* A hidden SSID cannot be selected by name; use manual entry. */
  if (len == 0 || *q != '"' || q[1] != ',') {
    return -1;
  }
  q += 2;
  p = (*q == '-') ? q + 1 : q;
  if (*p < '0' || *p > '9') {
    return -1;
  }
  rssi = strtol(q, &end, 10);
  if (rssi > 0 || rssi < -120 || (*end != ',' && *end != ')')) {
    return -1;
  }
  p = line + strlen(line);
  while (p > line && (p[-1] == ' ' || p[-1] == '\r' || p[-1] == '\n')) {
    p--;
  }
  if (p == line || p[-1] != ')') {
    return -1;
  }
  ap->rssi = (int)rssi;
  return 0;
}

