    lv_label_set_text(g_status,
                      g_font != NULL
                        ? "PC键盘输入+回车发送 | Tab中英 | Esc预警 | 1-5选字"
                        : "PC keys + Enter | Tab ZH/EN | Esc=Warn");
  }
}

