"""Check in-place RGB565 downsampling against a separate destination buffer."""
import subprocess
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
source = (ROOT / "app/edge_walker/ew_mirror.c").read_text(encoding="utf-8")
function = source[source.index("static void downscale_rgb565("):
                  source.index("static int pixel_equal565(")]
harness = r'''
#include <assert.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
'''
cases = r'''
int main(void) {
  int sizes[][2] = {{390,450}, {391,451}, {6,6}, {7,9}};
  unsigned t;
  int pad, scale;
  for (t = 0; t < sizeof(sizes)/sizeof(sizes[0]); t++) {
    for (pad = 0; pad <= 8; pad += 2) {
      for (scale = 1; scale <= 3; scale++) {
        int w = sizes[t][0], h = sizes[t][1], stride = w*2 + pad;
        int dw = w/scale, dh = h/scale;
        size_t n = (size_t)stride*h, i;
        uint8_t *src = malloc(n), *inplace = malloc(n), *out = malloc(n);
        assert(src && inplace && out);
        for (i = 0; i < n; i++) src[i] = (uint8_t)((i*37 + i/11) % 256);
        memcpy(inplace, src, n);
        downscale_rgb565(src,w,h,stride,scale,out,dw,dh);
        downscale_rgb565(inplace,w,h,stride,scale,inplace,dw,dh);
        assert(memcmp(out,inplace,(size_t)dw*dh*2) == 0);
        for (i = (size_t)dw*dh*2; i < n; i++) assert(inplace[i] == src[i]);
        free(src); free(inplace); free(out);
      }
    }
  }
  puts("PASS: 60 in-place cases, scales 1/2/3, padded rows, unchanged tail");
  return 0;
}
'''
with tempfile.TemporaryDirectory(prefix="ew_mirror_test_") as directory:
    path = Path(directory)
    (path / "test.c").write_text(harness + function + cases, encoding="utf-8")
    built = subprocess.run(
        ["gcc", "-std=c99", "-Wall", "-Wextra", "-Werror",
         "-Wno-unused-parameter", str(path / "test.c"),
         "-o", str(path / "test.exe")],
        capture_output=True, text=True,
    )
    if built.returncode != 0:
        raise RuntimeError(built.stdout + built.stderr)
    subprocess.run([str(path / "test.exe")], check=True)

"""Host regression tests for mirror pointer mapping and UTF-8 input commands."""

import importlib.util
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("ew_panel", ROOT / "tools/ew_panel.py")
assert SPEC and SPEC.loader
PANEL = importlib.util.module_from_spec(SPEC)
sys.modules[SPEC.name] = PANEL
SPEC.loader.exec_module(PANEL)


def main() -> None:
    assert PANEL.map_canvas_to_lcd(10, 20, 10, 20, 2.0, 390, 450) == (0, 0)
    assert PANEL.map_canvas_to_lcd(789, 919, 10, 20, 2.0, 390, 450) == (389, 449)
    assert PANEL.map_canvas_to_lcd(9, 20, 10, 20, 2.0, 390, 450) is None
    assert PANEL.map_canvas_to_lcd(389, 449, 0, 0, 2.0, 195, 225) == (389, 449)

    chinese = "你好，边缘行者"
    command = PANEL.remote_text_command(chinese)
    submit = PANEL.remote_text_command(chinese, submit=True)
    assert command == "@input " + chinese
    assert submit == "@submit " + chinese
    assert command.encode("utf-8").decode("utf-8") == command
    assert "\r" not in PANEL.remote_text_command("a\r\nb")
    assert len(PANEL.normalize_remote_text("中" * 300).encode("utf-8")) == 600
    print("PASS: pointer mapping and UTF-8 input/submit commands")


if __name__ == "__main__":
    main()

