void ew_mirror_set_enabled(int on)
{
  g_mirror_on = on ? 1 : 0;
  g_last_ms = 0;
  if (g_mirror_on) {
    mirror_apply_mode(g_mode);
  }
  g_log_next_frame = 1;
  printf("[ew-mirror] stream %s\n", g_mirror_on ? "ON" : "OFF");
