void ew_mirror_snap_once(void)
{
  int saved_scale = g_scale;

  /* 单帧调试：始终全分辨率，避免 FAST 1/3 再放大发糊 */
  g_scale = 1;
  g_log_next_frame = 1;
  (void)mirror_capture_send();
  g_scale = saved_scale;
}

void ew_mirror_tick(void)
{
  uint32_t now;

  if (!g_mirror_on || g_sending) {
    return;
  }
  now = mirror_now_ms();
  if (g_last_ms != 0 && (now - g_last_ms) < g_period_ms) {
    return;
  }
  g_last_ms = now;
  (void)mirror_capture_send();
}

