}

/* 一帧：喂硬件按键、跑当前页逻辑、刷 LVGL */
static void page_pump(void)
{
  uint32_t idle;

  hw_kbd_poll();
  ew_serial_ctl_poll();
  ew_mirror_tick();
  page_tick(g_page);
  idle = lv_timer_handler();
  if (idle == 0 || idle > EW_UI_FRAME_MS) {
    idle = EW_UI_FRAME_MS;
  }
  usleep(idle * 1000);
}

#endif /* __NuttX__ && CONFIG_LV_USE_NUTTX */

void ew_ui_loop(int start_in_chat)
{
#if defined(__NuttX__) && defined(CONFIG_LV_USE_NUTTX)
  if (!lv_is_initialized()) {
    printf("[ew-ui] LVGL not initialized\n");
    return;
  }
  ui_font_init();
  ew_agent_init();
  ew_serial_ctl_start();
  hw_kbd_open();
  g_page = start_in_chat ? EW_PAGE_CHAT : EW_PAGE_WARN;

  for (;;) {
    uint32_t gate;

    lv_obj_clean(lv_screen_active());
    page_build(g_page);
    lv_indev_reset(NULL, NULL);
    printf("[ew-ui] page=%d\n", (int)g_page);
    fflush(stdout);

    gate = lv_tick_get();
    g_page_pending = g_page;
  printf("[ew] reading %s, Ctrl-C to stop\n", EW_RADAR_DEV);

  for (;;) {
    ew_sniff_stats_t before = sniff;
    const ew_track_t *tp = NULL;
    bool had_bytes = false;
    bool had_frame = false;
    ew_decision_t d;
    struct timespec ts;
    uint32_t now = 0;
    int n = read(fd, buf, sizeof(buf));

    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
      now = (uint32_t)((uint64_t)ts.tv_sec * 1000u +
                       (uint64_t)ts.tv_nsec / 1000000u);
    }

    if (n > 0) {
      had_bytes = true;
      memset(&track, 0, sizeof(track));
      if (ew_ld2451_feed_sniff(buf, (unsigned)n, &sniff, &track) &&
          track.valid) {
        tp = &track;
      }
      had_frame = (sniff.frames_ok > before.frames_ok);
    } else {
      usleep(20000);
    }

    d = ew_hold_update(&hold, now, had_bytes, had_frame, tp);
    if (d.level != last) {
      printf("[ew] latch %s range=%.1fm %s link=%d\n",
             ew_alert_level_name(d.level), d.range_m, d.reason, (int)d.link);
      ew_agent_proactive_alert(d.level, d.range_m, d.reason);
      last = d.level;
    }
  }
#else
  printf("[ew] host stub: try `ew fake 10 2` or `ew alert soft`\n");
#endif
  return 0;
}

