static void pw_connect_cb(lv_event_t *e)
{
  const char *ssid;
  const char *pass;

  (void)e;
  if (g_ssid_ta == NULL || g_pw_ta == NULL) {
    return;
  }
  ssid = lv_textarea_get_text(g_ssid_ta);
  pass = lv_textarea_get_text(g_pw_ta);
