static int wait_prompt(int fd, int timeout_ms)
{
  char buf[96];
  unsigned n = 0;
  int waited = 0;

  buf[0] = '\0';
  while (waited < timeout_ms && n + 1 < sizeof(buf)) {
    char c;
    int r = read(fd, &c, 1);

    if (r == 1) {
      buf[n++] = c;
      buf[n] = '\0';
      if (strchr(buf, '>') != NULL) {
        return 0;
      }
      if (resp_fail(buf)) {
        return -1;
      }
      waited = 0;
    } else {
      usleep(20000);
      waited += 20;
    }
  }
  return -1;
}

/* 读到对端 CLOSED 或静默超时为止 */
static int collect_body(int fd, char *out, unsigned out_sz, int idle_ms)
{
  unsigned n = 0;
  int idle = 0;

  if (out_sz == 0) {
    return -1;
  }
  out[0] = '\0';
  while (idle < idle_ms && n + 1 < out_sz) {
    char c;
    int r = read(fd, &c, 1);

    if (r == 1) {
      out[n++] = c;
      out[n] = '\0';
      idle = 0;
      if (n > 24 && strstr(out, "CLOSED") != NULL) {
        return (int)n;
      }
    } else {
      usleep(20000);
      idle += 20;
    }
  }
  return (int)n;
}

