  lv_label_set_long_mode(lab, LV_LABEL_LONG_DOT);
  lv_obj_set_width(lab, lv_pct(100));
  lv_obj_align(lab, LV_ALIGN_LEFT_MID, 0, 0);
  if (cb != NULL) {
    lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, ud);
  }
