void ew_wifi_ui_tick(void)
{
  int was_join;

  if (!g_job_done) {
    return;
  }
  g_job_done = 0;
  was_join = (g_job == JOB_JOIN);

  if (g_status != NULL) {
    lv_label_set_text(g_status, g_status_text);
