  g_more_btn = NULL;
  g_ime_page = 0;
  g_wait_bubble = NULL;
  g_busy = 0;
  g_reply_ready = 0;
  build_ui();
  apply_remote_pending();
}

static void page_build(ew_page_t page)
{
  switch (page) {
    case EW_PAGE_CHAT:
      chat_page_build();
      break;
    case EW_PAGE_WIFI:
      ew_wifi_ui_build();
      break;
    default:
      alert_lcd_attach_warn_ui();
      break;
  }
}

static void page_tick(ew_page_t page)
{
  switch (page) {
    case EW_PAGE_CHAT:
      poll_reply();
      break;
    case EW_PAGE_WIFI:
      ew_wifi_ui_tick();
      break;
    default:
      alert_lcd_warn_tick();
      break;
  }
}

static void page_teardown(ew_page_t page)
{
  switch (page) {
    case EW_PAGE_CHAT:
      hide_kb();
      break;
    case EW_PAGE_WIFI:
      ew_wifi_ui_teardown();
      break;
    default:
      alert_lcd_detach_warn_ui();
      break;
  }
}

/* 一帧：喂硬件按键、跑当前页逻辑、刷 LVGL */
static void page_pump(void)
{
  uint32_t idle;

  hw_kbd_poll();
  ew_serial_ctl_poll();
  ew_mirror_tick();
  page_tick(g_page);
  idle = lv_timer_handler();
  if (idle == 0 || idle > EW_UI_FRAME_MS) {
    idle = EW_UI_FRAME_MS;
  }
  usleep(idle * 1000);
}

#endif /* __NuttX__ && CONFIG_LV_USE_NUTTX */

void ew_ui_loop(int start_in_chat)
{
#if defined(__NuttX__) && defined(CONFIG_LV_USE_NUTTX)
  if (!lv_is_initialized()) {
    printf("[ew-ui] LVGL not initialized\n");
    return;
  }
  ui_font_init();
  ew_agent_init();
  ew_serial_ctl_start();
  hw_kbd_open();
  g_page = start_in_chat ? EW_PAGE_CHAT : EW_PAGE_WARN;

  for (;;) {
    uint32_t gate;

    lv_obj_clean(lv_screen_active());
    page_build(g_page);
    lv_indev_reset(NULL, NULL);
    printf("[ew-ui] page=%d\n", (int)g_page);
    fflush(stdout);

    gate = lv_tick_get();
    g_page_pending = g_page;
    while (lv_tick_elaps(gate) < EW_UI_GATE_MS) {
      page_pump();
    }

    /* 门限期内的误触不算数，从这里才开始接受切页 */
    g_page_pending = g_page;
    while (g_page_pending == g_page) {
      page_pump();
    }

