typedef enum {
  JOB_IDLE = 0,
  JOB_REFRESH,      /* 查链路状态 + 扫描 */
  JOB_JOIN
} ew_job_t;

static lv_obj_t *g_list;
static lv_obj_t *g_status;
static lv_obj_t *g_scan_btn;
