+static int copy_file(const char *src, const char *dst)
+{
+  FILE *in;
+  FILE *out;
+  char buf[256];
+  size_t n;
+  int rc = -1;
+
+  in = fopen(src, "rb");
+  if (in == NULL) {
+    return -1;
+  }
+  out = fopen(dst, "wb");
+  if (out == NULL) {
+    fclose(in);
