+    }
+  }
+  if (ferror(in) == 0 && fflush(out) == 0) {
+    rc = 0;
+  }
+
+done:
+  fclose(out);
+  fclose(in);
+  if (rc != 0) {
+    unlink(dst);
+  }
+  return rc;
+}
