static void start_ask(const char *text)
{
  pthread_t th;
  pthread_attr_t attr;
  const char *p;

  if (text == NULL || g_busy) {
    return;
  }
  while (*text == ' ') {
    text++;
  }
  if (text[0] == '\0') {
    return;
  }

  strncpy(g_pending, text, sizeof(g_pending) - 1);
  g_pending[sizeof(g_pending) - 1] = '\0';
