/****************************************************************************
 * 边缘行者主程序（郑子轩）
 *
 * 用法见 `ew help`。板子上由 rcS 启动 `ew boot`，其余子命令只用于台架调试。
 ****************************************************************************/

#include "alert_output.h"
#include "alert_buzzer.h"
#include "alert_lcd.h"
#include "ew_chat.h"
#include "ew_ld2451.h"
#include "ew_llm.h"
