def normalize_remote_text(text: str, max_bytes: int = MAX_REMOTE_UTF8) -> str:
    """Make one UTF-8 console line without splitting a code point."""
    clean = text.replace("\r", " ").replace("\n", " ")
    raw = clean.encode("utf-8")
    if len(raw) <= max_bytes:
