/* 读到对端 CLOSED 或静默超时为止 */
static int collect_body(int fd, char *out, unsigned out_sz, int idle_ms)
{
  unsigned n = 0;
  int idle = 0;

  if (out_sz == 0) {
    return -1;
  }
  out[0] = '\0';
  while (idle < idle_ms && n + 1 < out_sz) {
    char c;
    int r = read(fd, &c, 1);

    if (r == 1) {
      out[n++] = c;
      out[n] = '\0';
      idle = 0;
      if (n > 24 && strstr(out, "CLOSED") != NULL) {
        return (int)n;
      }
    } else {
      usleep(20000);
      idle += 20;
    }
  }
  return (int)n;
}

