    g_job_result = ew_wifi_forget();
    snprintf(g_status_text, sizeof(g_status_text), "%s",
             g_job_result == 0 ? "disconnected - saved network removed"
                               : "disconnect failed - network kept");
  } else {
    ew_wifi_ap_t scanned[EW_WIFI_SCAN_MAX];
    char ip[24];
