static void q_push(const char *line)
{
  pthread_mutex_lock(&g_q.mu);
  if (((g_q.tail + 1) % EW_CTL_Q_MAX) != g_q.head) {
    snprintf(g_q.lines[g_q.tail], EW_CTL_LINE_MAX, "%s", line);
