{
  lv_obj_t *row;
  lv_obj_t *lab;
  lv_color_t bg;

  if (g_list == NULL || text == NULL) {
    return;
  }

  while (lv_obj_get_child_count(g_list) >= EW_CHAT_MAX_BUBBLE) {
    lv_obj_t *old = lv_obj_get_child(g_list, 0);
    if (old != NULL) {
      if (old == g_wait_bubble) {
        g_wait_bubble = NULL;
      }
      lv_obj_delete(old);
    } else {
      break;
    }
