static void handle_zh_key(const char *txt)
{
  size_t n;

  if (txt == NULL || txt[0] == '\0') {
    return;
  }
  if (strcmp(txt, LV_SYMBOL_BACKSPACE) == 0 || strcmp(txt, "Del") == 0) {
    n = strlen(g_py);
    if (n > 0) {
      g_py[n - 1] = '\0';
      g_ime_page = 0;
      refresh_cands();
