    if (g_zh) {
      handle_zh_key(LV_SYMBOL_OK);
    } else {
      send_from_ta();
    }
    return;
  }
  if (code == KEY_ESC) {
    hide_kb();
    ew_ui_goto(EW_PAGE_WARN);
    return;
