    hide_kb();
    if (g_zh && g_ime_bar != NULL) {
      lv_obj_clear_flag(g_ime_bar, LV_OBJ_FLAG_HIDDEN);
    }
    return;
  }
  if (g_zh && code >= KEY_1 && code <= KEY_5) {
    int idx = (int)(code - KEY_1);
    if (g_cands[idx] != NULL &&
        !lv_obj_has_flag(g_cands[idx], LV_OBJ_FLAG_HIDDEN)) {
